def _compare_entry(
    key: str,
    candidate: dict[str, Any],
    relation: str,
    *,
    local: dict[str, Any] | None,
    remote: dict[str, Any] | None,
) -> dict[str, Any]:
    """Build one per-candidate difference entry in its fixed field order."""
